1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE = 0.1;
3	
4	const BASE_PREMIUM: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	};
9	
10	type Item = { type: string };
11	type Scenario = {
12	  customer: { yearsWithMHPCO: number };
13	  steps: Array<{ op: "quote"; items: Item[] }>;
14	};
15	
16	const itemPremium = (item: Item): number =>
17	  BASE_PREMIUM[item.type] * (1 + FIRST_INSURANCE_SURCHARGE);
18	
19	const roundUpInFavorOfInsurer = (amount: number): number =>
20	  Math.ceil(Math.round(amount * 1e6) / 1e6);
21	
22	const quotePremium = (items: Item[]): number => {
23	  const itemsTotal = items.reduce((sum, item) => sum + itemPremium(item), 0);
24	  return roundUpInFavorOfInsurer(itemsTotal + PROCESSING_FEE);
25	};
26	
27	export const runScenario = (scenario: unknown): unknown => {
28	  const { steps } = scenario as Scenario;
29	  const results = steps.map((step) => ({ premium: quotePremium(step.items) }));
30	  return { results };
31	};
